  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "A human PET study confirmed actual influx of tryptophan into the brain after systemic administration, providing direct evidence of meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "AZD0530 was detected in plasma, brain, and CSF of mice after systemic dosing, with a brain half-life of 16 hours, demonstrating meaningful blood-brain barrier penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "5-[18F]FEHTrp showed low brain uptake of 0.84 %ID/g in mice, indicating limited CNS access for this close analog.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most structurally similar molecules with direct in-vivo systemic evidence show meaningful CNS access, including human tryptophan influx, mouse brain/CSF exposure for AZD0530, and favorable brain/plasma or brain uptake for other analogs. Two fluorinated tryptophan analogs showed low brain uptake, but the overall direct experimental record supports a pass prediction.",
  "evidence_gaps": [
    "Morgan similarities are only ~0.27-0.31, limiting structural transferability.",
    "Two close tryptophan analogs showed low brain uptake, creating mixed evidence.",
    "Some positive PET records used intracranial glioma models where the BBB may be altered."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

